"use client"

import { useState } from "react"
import Link from "next/link"
import { Ticket, Download, QrCode, Calendar, MapPin, Clock, CheckCircle, XCircle } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Header } from "@/components/header"
import { Badge } from "@/components/ui/badge"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { mockEvents } from "@/lib/events-data"

// Мок данные для билетов
interface TicketData {
  id: string
  eventId: string
  purchaseDate: string
  ticketNumber: string
  status: "active" | "used" | "cancelled"
  quantity: number
  totalPrice: number
}

const mockTickets: TicketData[] = [
  {
    id: "t1",
    eventId: "1",
    purchaseDate: "2025-11-25",
    ticketNumber: "EVT-2025-001234",
    status: "active",
    quantity: 2,
    totalPrice: 1000,
  },
  {
    id: "t2",
    eventId: "5",
    purchaseDate: "2025-11-20",
    ticketNumber: "EVT-2025-001235",
    status: "active",
    quantity: 1,
    totalPrice: 1500,
  },
  {
    id: "t3",
    eventId: "6",
    purchaseDate: "2025-11-15",
    ticketNumber: "EVT-2025-001236",
    status: "active",
    quantity: 2,
    totalPrice: 5000,
  },
  {
    id: "t4",
    eventId: "3",
    purchaseDate: "2025-10-10",
    ticketNumber: "EVT-2025-000987",
    status: "used",
    quantity: 1,
    totalPrice: 300,
  },
  {
    id: "t5",
    eventId: "2",
    purchaseDate: "2025-09-05",
    ticketNumber: "EVT-2025-000654",
    status: "cancelled",
    quantity: 1,
    totalPrice: 2000,
  },
]

export default function TicketsPage() {
  const [selectedTicket, setSelectedTicket] = useState<string | null>(null)

  const getEventById = (eventId: string) => mockEvents.find((e) => e.id === eventId)

  const activeTickets = mockTickets.filter((t) => t.status === "active")
  const pastTickets = mockTickets.filter((t) => t.status === "used" || t.status === "cancelled")

  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleDateString("ru-RU", {
      day: "numeric",
      month: "long",
      year: "numeric",
    })
  }

  const getStatusBadge = (status: TicketData["status"]) => {
    switch (status) {
      case "active":
        return <Badge className="bg-green-600">Активный</Badge>
      case "used":
        return <Badge variant="secondary">Использован</Badge>
      case "cancelled":
        return <Badge variant="destructive">Отменён</Badge>
    }
  }

  const renderTicketCard = (ticket: TicketData, showActions = true) => {
    const event = getEventById(ticket.eventId)
    if (!event) return null

    const isExpanded = selectedTicket === ticket.id

    return (
      <div
        key={ticket.id}
        className="rounded-xl bg-card border border-border overflow-hidden"
      >
        <div className="flex flex-col md:flex-row">
          <div className="md:w-48 h-32 md:h-auto relative">
            <img
              src={event.image}
              alt={event.title}
              className="w-full h-full object-cover"
            />
            <div className="absolute inset-0 bg-gradient-to-r from-transparent to-black/20 md:bg-gradient-to-t" />
          </div>

          <div className="flex-1 p-4 space-y-3">
            <div className="flex items-start justify-between gap-4">
              <div>
                <div className="flex items-center gap-2 mb-1">
                  {getStatusBadge(ticket.status)}
                  <Badge variant="outline">{event.category}</Badge>
                </div>
                <h3 className="text-lg font-bold text-foreground">{event.title}</h3>
              </div>
              {showActions && ticket.status === "active" && (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setSelectedTicket(isExpanded ? null : ticket.id)}
                >
                  <QrCode className="w-4 h-4 mr-2" />
                  QR-код
                </Button>
              )}
            </div>

            <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-sm">
              <div className="flex items-center gap-2 text-muted-foreground">
                <Calendar className="w-4 h-4" />
                <span>{formatDate(event.date)}</span>
              </div>
              <div className="flex items-center gap-2 text-muted-foreground">
                <Clock className="w-4 h-4" />
                <span>{event.time}</span>
              </div>
              <div className="flex items-center gap-2 text-muted-foreground">
                <MapPin className="w-4 h-4" />
                <span>{event.location}</span>
              </div>
              <div className="flex items-center gap-2 text-muted-foreground">
                <Ticket className="w-4 h-4" />
                <span>{ticket.quantity} шт.</span>
              </div>
            </div>

            <div className="flex items-center justify-between pt-3 border-t border-border">
              <div>
                <div className="text-sm text-muted-foreground">Номер билета</div>
                <div className="font-mono text-foreground">{ticket.ticketNumber}</div>
              </div>
              <div className="text-right">
                <div className="text-sm text-muted-foreground">Стоимость</div>
                <div className="font-bold text-foreground">{ticket.totalPrice} ₽</div>
              </div>
            </div>
          </div>
        </div>

        {/* QR Code Section */}
        {isExpanded && ticket.status === "active" && (
          <div className="border-t border-border p-6 bg-muted/30">
            <div className="flex flex-col md:flex-row items-center gap-6">
              <div className="w-48 h-48 bg-white rounded-xl p-4 flex items-center justify-center">
                {/* Fake QR Code */}
                <div className="w-full h-full bg-[url('data:image/svg+xml;base64,')] bg-contain" />
              </div>
              <div className="text-center md:text-left space-y-3">
                <h4 className="font-semibold text-foreground">Покажите этот QR-код на входе</h4>
                <p className="text-sm text-muted-foreground">
                  QR-код является вашим билетом. Сохраните его или сделайте скриншот для быстрого доступа.
                </p>
                <div className="flex gap-2 justify-center md:justify-start">
                  <Button variant="outline" size="sm">
                    <Download className="w-4 h-4 mr-2" />
                    Скачать PDF
                  </Button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-background">
      <Header />

      <main className="max-w-5xl mx-auto px-4 py-8">
        {/* Page Title */}
        <div className="flex items-center gap-3 mb-8">
          <div className="p-2 rounded-lg bg-primary/10">
            <Ticket className="w-5 h-5 text-primary" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-foreground">Мои билеты</h1>
            <p className="text-sm text-muted-foreground">{mockTickets.length} билетов</p>
          </div>
        </div>
        {/* Stats */}
        <div className="grid grid-cols-3 gap-4 mb-8">
          <div className="p-4 rounded-xl bg-card border border-border text-center">
            <div className="flex items-center justify-center w-10 h-10 mx-auto mb-2 rounded-full bg-green-100 dark:bg-green-900/30">
              <CheckCircle className="w-5 h-5 text-green-600" />
            </div>
            <div className="text-2xl font-bold text-foreground">{activeTickets.length}</div>
            <div className="text-sm text-muted-foreground">Активных</div>
          </div>
          <div className="p-4 rounded-xl bg-card border border-border text-center">
            <div className="flex items-center justify-center w-10 h-10 mx-auto mb-2 rounded-full bg-muted">
              <Ticket className="w-5 h-5 text-muted-foreground" />
            </div>
            <div className="text-2xl font-bold text-foreground">
              {mockTickets.filter((t) => t.status === "used").length}
            </div>
            <div className="text-sm text-muted-foreground">Использовано</div>
          </div>
          <div className="p-4 rounded-xl bg-card border border-border text-center">
            <div className="flex items-center justify-center w-10 h-10 mx-auto mb-2 rounded-full bg-red-100 dark:bg-red-900/30">
              <XCircle className="w-5 h-5 text-red-600" />
            </div>
            <div className="text-2xl font-bold text-foreground">
              {mockTickets.filter((t) => t.status === "cancelled").length}
            </div>
            <div className="text-sm text-muted-foreground">Отменено</div>
          </div>
        </div>

        <Tabs defaultValue="active" className="space-y-6">
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="active">Предстоящие ({activeTickets.length})</TabsTrigger>
            <TabsTrigger value="past">История ({pastTickets.length})</TabsTrigger>
          </TabsList>

          <TabsContent value="active" className="space-y-4">
            {activeTickets.length > 0 ? (
              activeTickets.map((ticket) => renderTicketCard(ticket))
            ) : (
              <div className="flex flex-col items-center justify-center py-20 text-center">
                <div className="w-20 h-20 rounded-full bg-muted flex items-center justify-center mb-6">
                  <Ticket className="w-10 h-10 text-muted-foreground" />
                </div>
                <h2 className="text-2xl font-bold text-foreground mb-2">Нет активных билетов</h2>
                <p className="text-muted-foreground mb-6 max-w-md">
                  У вас пока нет билетов на предстоящие мероприятия
                </p>
                <Link href="/">
                  <Button>Найти мероприятия</Button>
                </Link>
              </div>
            )}
          </TabsContent>

          <TabsContent value="past" className="space-y-4">
            {pastTickets.length > 0 ? (
              pastTickets.map((ticket) => renderTicketCard(ticket, false))
            ) : (
              <div className="flex flex-col items-center justify-center py-20 text-center">
                <div className="w-20 h-20 rounded-full bg-muted flex items-center justify-center mb-6">
                  <Ticket className="w-10 h-10 text-muted-foreground" />
                </div>
                <h2 className="text-2xl font-bold text-foreground mb-2">История пуста</h2>
                <p className="text-muted-foreground">
                  Здесь будут отображаться прошедшие и отменённые билеты
                </p>
              </div>
            )}
          </TabsContent>
        </Tabs>
      </main>
    </div>
  )
}
